// 1. Inspect the embedded CC0 CSV using sheetframe; no runtime download.
raw, err := os.ReadFile("penguins.csv")
if err != nil { panic(err) }
sourceSHA := fmt.Sprintf("%x", sha256.Sum256(raw))
if sourceSHA != "f204db2c753b0937caac3cb35258562c14f073e4bbc76be24b4c51ce22767a93" { panic("source checksum changed; review data and protocol") }
frame, err := sheetframe.ReadCSV(bytes.NewReader(raw))
if err != nil { panic(err) }
sourceRows, sourceColumns := frame.Shape()
fmt.Printf("Source: %d rows x %d columns; SHA256 %s\n", sourceRows, sourceColumns, sourceSHA)
fmt.Printf("Raw DataFrame schema: %v\nFirst five rows:\n", frame.Schema())
if err = frame.Head(5).WriteCSV(os.Stdout); err != nil { panic(err) }
fmt.Println("Literal NA is a missing marker; affected columns initially infer as strings.")
// A library-neutral table artifact makes Head visible in GoBook's result area.
rawPreview := map[string]any{"format": "gobook.table.v1", "title": "Raw DataFrame · Head(8)", "columns": frame.Columns(), "rows": frame.Head(8).Records()}
rawPreviewFile, err := os.Create("data-preview.json")
if err != nil { panic(err) }
if err = json.NewEncoder(rawPreviewFile).Encode(rawPreview); err != nil { rawPreviewFile.Close(); panic(err) }
if err = rawPreviewFile.Close(); err != nil { panic(err) }

// 2. Explicit missing policy for predictor/response; preserve source row IDs.
nextCSVRow := 1
frame, err = frame.WithColumn("source_csv_row", func(row sheetframe.Row) (any, error) {
    nextCSVRow++
    return float64(nextCSVRow), nil // Header is CSV row 1.
})
if err != nil { panic(err) }
for _, column := range []string{"flipper_length_mm", "body_mass_g"} {
    frame, err = frame.WithColumn(column, func(row sheetframe.Row) (any, error) {
        value, ok := row.Get(column)
        if !ok { return nil, fmt.Errorf("missing column %s", column) }
        if value == nil || value == "NA" { return nil, nil }
        if number, ok := value.(float64); ok { return number, nil }
        text, ok := value.(string)
        if !ok { return nil, fmt.Errorf("unexpected %s type %T", column, value) }
        number, parseErr := strconv.ParseFloat(text, 64)
        if parseErr != nil || math.IsNaN(number) || math.IsInf(number, 0) { return nil, fmt.Errorf("invalid %s value %q", column, text) }
        return number, nil
    })
    if err != nil { panic(err) }
}
missingFlipper, err := frame.Filter("flipper_length_mm", sheetframe.IsNull, nil)
if err != nil { panic(err) }
missingMass, err := frame.Filter("body_mass_g", sheetframe.IsNull, nil)
if err != nil { panic(err) }
missingFlipperCount, _ := missingFlipper.Shape()
missingMassCount, _ := missingMass.Shape()
clean, err := frame.Query().Filter("flipper_length_mm", sheetframe.NotNull, nil).Filter("body_mass_g", sheetframe.NotNull, nil).Collect()
if err != nil { panic(err) }
completeRows, _ := clean.Shape()
excludedRows := sourceRows - completeRows
fmt.Printf("Missing flipper %d; missing mass %d; excluded union %d; complete pairs %d\n", missingFlipperCount, missingMassCount, excludedRows, completeRows)
fmt.Println("Missing sex/bill values do not exclude rows; this model does not use them.")
fmt.Printf("Cleaned DataFrame schema: %v\n", clean.Schema())
numeric, err := clean.Select("flipper_length_mm", "body_mass_g")
if err != nil { panic(err) }
var numericCSV bytes.Buffer
if err = numeric.WriteCSV(&numericCSV); err != nil { panic(err) }
data, err := tabular.ReadCSV(&numericCSV, "flipper_length_mm", "body_mass_g")
if err != nil { panic(err) }
// Show the nullable numeric schema's paired rows after explicit filtering.
cleanPreview := map[string]any{"format": "gobook.table.v1", "title": "Clean DataFrame · Head(8)", "columns": clean.Columns(), "rows": clean.Head(8).Records()}
cleanPreviewFile, err := os.Create("clean-preview.json")
if err != nil { panic(err) }
if err = json.NewEncoder(cleanPreviewFile).Encode(cleanPreview); err != nil { cleanPreviewFile.Close(); panic(err) }
if err = cleanPreviewFile.Close(); err != nil { panic(err) }

// 3. Seeded paired shuffle; first floor(80%*n) train, remainder held out.
const splitSeed int64 = 42
order := rand.New(rand.NewSource(splitSeed)).Perm(len(data.X))
shuffled := tabular.Dataset{X: make([]float64, len(order)), Y: make([]float64, len(order))}
for i, original := range order { shuffled.X[i], shuffled.Y[i] = data.X[original], data.Y[original] }
trainCount := len(order) * 8 / 10
train, heldout, err := tabular.Split(shuffled, trainCount)
if err != nil { panic(err) }
model, err := tabular.Fit(train) // Held-out responses never enter fitting.
if err != nil { panic(err) }
defer model.Close()
predicted, err := model.Predict(heldout.X)
if err != nil { panic(err) }
modelMetrics, err := tabular.Evaluate(heldout.Y, predicted)
if err != nil { panic(err) }
trainingMean := 0.0
for _, y := range train.Y { trainingMean += y / float64(len(train.Y)) }
baseline := make([]float64, len(heldout.Y))
for i := range baseline { baseline[i] = trainingMean }
baselineMetrics, err := tabular.Evaluate(heldout.Y, baseline)
if err != nil { panic(err) }
fmt.Printf("Seed %d; training %d; held out %d; training mean %.3f g\n", splitSeed, len(train.X), len(heldout.X), trainingMean)
fmt.Printf("OLS:      MAE %.3f g | RMSE %.3f g | R2 %.6f\n", modelMetrics.MAE, modelMetrics.RMSE, modelMetrics.R2)
fmt.Printf("Baseline: MAE %.3f g | RMSE %.3f g | R2 %.6f\n", baselineMetrics.MAE, baselineMetrics.RMSE, baselineMetrics.R2)
fmt.Println("One split is educational, not external validation; species/sex/island/year may confound the pooled relationship.")

// 4. Relationship and held-out diagnostics; residual = actual - predicted.
trainMin, trainMax := train.X[0], train.X[0]
for _, x := range train.X { trainMin, trainMax = math.Min(trainMin, x), math.Max(trainMax, x) }
fitX := []float64{trainMin, trainMax}
fitY, err := model.Predict(fitX)
if err != nil { panic(err) }
if err = chartframe.New("Palmer Penguins: training fit and held-out observations").Labels("Flipper length (mm)", "Body mass (g)").Scatter("training", train.X, train.Y).Scatter("held out", heldout.X, heldout.Y).Line("OLS fitted on training only", fitX, fitY).Save("relationship.svg"); err != nil { panic(err) }
actualPredicted := chartframe.New("Held-out actual vs predicted mass").Labels("Actual mass (g)", "Predicted mass (g)")
low, high := heldout.Y[0], heldout.Y[0]
residuals := make([]float64, len(predicted))
predictMin, predictMax := predicted[0], predicted[0]
for i := range predicted {
    low = math.Min(low, math.Min(heldout.Y[i], predicted[i]))
    high = math.Max(high, math.Max(heldout.Y[i], predicted[i]))
    residuals[i] = heldout.Y[i] - predicted[i]
    predictMin, predictMax = math.Min(predictMin, predicted[i]), math.Max(predictMax, predicted[i])
}
for _, species := range []string{"Adelie", "Chinstrap", "Gentoo"} {
    actualSpecies, predictedSpecies := []float64{}, []float64{}
    for i := range predicted {
        label, getErr := clean.At(order[trainCount+i], "species")
        if getErr != nil { panic(getErr) }
        if label == species { actualSpecies = append(actualSpecies, heldout.Y[i]); predictedSpecies = append(predictedSpecies, predicted[i]) }
    }
    if len(actualSpecies) > 0 { actualPredicted.Scatter(species, actualSpecies, predictedSpecies) }
}
if err = actualPredicted.Line("perfect prediction", []float64{low, high}, []float64{low, high}).Save("actual-vs-predicted.svg"); err != nil { panic(err) }
if err = chartframe.New("Held-out residuals: inspect bias and changing spread").Labels("Predicted mass (g)", "Actual minus predicted (g)").Scatter("held-out residuals", predicted, residuals).Line("zero residual", []float64{predictMin, predictMax}, []float64{0, 0}).Save("residuals.svg"); err != nil { panic(err) }
fmt.Println("Saved relationship.svg, actual-vs-predicted.svg (by species), residuals.svg.")

// 5. Export metrics/model/predictions and verify model serialization parity.
report := map[string]any{
    "schema": "gobook.penguins-evaluation", "version": 1,
    "source_commit": "8957207b78d6ccd1b4654a9dd9c9041b657478ab", "source_sha256": sourceSHA,
    "source_rows": sourceRows, "missing_flipper": missingFlipperCount, "missing_mass": missingMassCount,
    "excluded_union": excludedRows, "complete_rows": completeRows,
    "seed": splitSeed, "split_method": "math/rand.NewSource(seed).Perm; first floor(0.8*n) train",
    "training_rows": len(train.X), "heldout_rows": len(heldout.X),
    "predictor": "flipper_length_mm", "response": "body_mass_g", "training_mean_g": trainingMean,
    "ols": modelMetrics, "training_mean_baseline": baselineMetrics,
    "limitations": "One row split of pooled species; no species/sex/island/year adjustment, tuning, independent population or causal validation.",
}
reportFile, err := os.Create("metrics.json")
if err != nil { panic(err) }
encoder := json.NewEncoder(reportFile)
encoder.SetIndent("", "  ")
if err = encoder.Encode(report); err != nil { reportFile.Close(); panic(err) }
if err = reportFile.Close(); err != nil { panic(err) }
modelFile, err := os.Create("model.json")
if err != nil { panic(err) }
if err = model.Save(modelFile); err != nil { modelFile.Close(); panic(err) }
if err = modelFile.Close(); err != nil { panic(err) }
modelInput, err := os.Open("model.json")
if err != nil { panic(err) }
restored, err := tabular.Load(modelInput)
closeErr := modelInput.Close()
if err != nil { panic(err) }
defer restored.Close()
if closeErr != nil { panic(closeErr) }
roundtrip, err := restored.Predict(heldout.X)
if err != nil { panic(err) }
rows := make([][]any, len(predicted))
for i := range predicted {
    if math.Float64bits(roundtrip[i]) != math.Float64bits(predicted[i]) { panic("serialized model changed predictions") }
    originalRow := order[trainCount+i]
    sourceRow, getErr := clean.At(originalRow, "source_csv_row")
    if getErr != nil { panic(getErr) }
    species, getErr := clean.At(originalRow, "species")
    if getErr != nil { panic(getErr) }
    rows[i] = []any{sourceRow, species, heldout.X[i], heldout.Y[i], predicted[i], baseline[i], residuals[i]}
}
export, err := sheetframe.New([]string{"source_csv_row", "species", "flipper_length_mm", "actual_mass_g", "predicted_mass_g", "baseline_mass_g", "residual_g"}, rows)
if err != nil { panic(err) }
predictionsFile, err := os.Create("predictions.csv")
if err != nil { panic(err) }
if err = export.WriteCSV(predictionsFile); err != nil { predictionsFile.Close(); panic(err) }
if err = predictionsFile.Close(); err != nil { panic(err) }
if err = restored.Close(); err != nil { panic(err) }
if err = model.Close(); err != nil { panic(err) }
fmt.Println("Exported metrics.json, model.json, predictions.csv; restored predictions match exactly; models closed.")
